'use client';
import { useState, useRef, useEffect, useCallback, useMemo, type PointerEvent } from 'react';
import { ShoppingBag, Package, History, Star, SlidersHorizontal, Search, Plus, ArrowUp, Mic, MicOff, MoreHorizontal, ChevronDown, ChevronRight, ArrowUpRight, Check, CheckCheck, Cloud, CloudOff, WifiOff, LoaderCircle, X, ShoppingBasket, ArrowDownToLine, FileUp, Printer, ListFilter, Layers, Copy, ArrowLeftRight, RefreshCw, Box, Clock3, AlertCircle, Sparkles, LayoutTemplate, Merge, ShieldCheck, Trash2, GripVertical, Circle, Utensils, Shirt, Zap, Armchair } from 'lucide-react';
import { useShoppingStore } from '@/lib/client-store';
