  const transition = (item: ShoppingItem, next: ItemStatus) => { const purchase = (next === 'purchased' || next === 'received') && !COMPLETE.includes(item.status); updateItem(item.id, { status: next, ...(purchase ? { purchasedAt: TODAY(), purchasedQuantity: item.quantity, stock: item.stock + Math.max(0, item.quantity - item.purchasedQuantity), checkedAt: TODAY() } : {}) }, `${item.name}を${STATUS_LABELS[next]}に変更`); };
